import React,{useState} from 'react';import{createRoot}from'react-dom/client';import '../../src/renderer/src/styles.css';import{Projection}from'../../../../examples/dashboard-consumer/Projection';
const load=async()=>{const r=await fetch('/__proof/projection');if(!r.ok)throw Error('Fixture unavailable');return r.json();};
function Fixture(){const[status,setStatus]=useState<any>(null),[labels,setLabels]=useState({});const run=async(action:string)=>{const r=await fetch('/__proof/'+action,{method:'POST'});if(!r.ok)throw Error('Fixture action failed');const next=await r.json();setStatus(next);setLabels(next.labels);};return <main style={{padding:24}}><p>PRUEBA LOCAL SINTÉTICA · Sin inferencias ni operaciones externas. Las etiquetas de departamentos/cuentas son ficticias.</p><div style={{display:'flex',gap:12,marginBottom:20}}><button onClick={()=>void run('dispatch')}>Ejecutar dos tareas simuladas</button><button onClick={()=>void run('restart')}>Reiniciar transporte y recuperar ack</button></div>{status&&<p>Operaciones locales ejecutadas: {status.executions} · Pendientes de confirmar: {status.sender.pending} · Estado del sender: {status.sender.reason}</p>}<Projection expectedScope={{orgRef:'synthetic-org',projectRef:'synthetic-project'}} load={load} interval={500} labels={labels}/></main>};createRoot(document.getElementById('root')!).render(<Fixture/>);
